-- 2026 sectors and sub-sectors of the SEPLAT EHOR planting site (project T4L), from the 2026 Sectoring Plan
-- (BE.C.206): 24 sectors (plan letters A-X) of 5 sub-sectors each, numbered south to north. Source files:
-- SEPLAT_EHOR_2026_Sectors_and_Subsectors.kml (outlines) and SEPLAT_EHOR_2026_Subsectors.csv (centroids). Issue #85.
--
-- Sectors S1-S24 and their sub-sectors SS1-SS5 are updated in place when they exist (outline, reference point, name),
-- so every tree keeps the sector and sub-sector it was recorded in; missing ones are created. Other 2026 areas are
-- removed only when nothing refers to them; areas holding trees or officer assignments are kept as they are.
-- Does nothing when the project or its 2026 planting year does not exist. Safe to run again.

CREATE TEMP TABLE plan_sectors (n int, letter text, outline text) ON COMMIT DROP;

CREATE TEMP TABLE plan_sub_sectors (sector_n int, n int, lat numeric, lon numeric, outline text) ON COMMIT DROP;

DO $$
DECLARE
  pid uuid;
  yid uuid;
  kept int;
BEGIN
  SELECT id INTO pid FROM projects WHERE short_code = 'T4L';
  IF pid IS NULL THEN RAISE NOTICE '2026 sectoring plan: project T4L not found, nothing changed'; RETURN; END IF;
  SELECT id INTO yid FROM planting_years WHERE project_id = pid AND year_label = '2026';
  IF yid IS NULL THEN RAISE NOTICE '2026 sectoring plan: planting year 2026 not found, nothing changed'; RETURN; END IF;

  -- Sectors: update S1..S24 of 2026 in place, create the missing ones.
  UPDATE sectors s SET
      name = 'Sector ' || p.n,
      description = 'Plan letter ' || p.letter || ' · 2026 Sectoring Plan (BE.C.206)',
      boundary_geometry = ST_SetSRID(ST_GeomFromText(p.outline), 4326),
      reference_latitude = ST_Y(ST_PointOnSurface(ST_GeomFromText(p.outline))),
      reference_longitude = ST_X(ST_PointOnSurface(ST_GeomFromText(p.outline))),
      active = true, updated_at = now()
    FROM plan_sectors p
   WHERE s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.n;
  SELECT pid, yid, 'Sector ' || p.n, 'S' || p.n, 'Plan letter ' || p.letter || ' · 2026 Sectoring Plan (BE.C.206)',
         ST_Y(ST_PointOnSurface(ST_GeomFromText(p.outline))), ST_X(ST_PointOnSurface(ST_GeomFromText(p.outline))),
         ST_SetSRID(ST_GeomFromText(p.outline), 4326)
    FROM plan_sectors p
   WHERE NOT EXISTS (SELECT 1 FROM sectors s WHERE s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.n);

  -- Sub-sectors: update SS1..SS5 of each sector in place, create the missing ones.
  UPDATE sub_sectors ss SET
      name = 'Sub-sector ' || p.n,
      description = 'Plan ' || ps.letter || p.n || ' · 2026 Sectoring Plan (BE.C.206)',
      boundary_geometry = ST_SetSRID(ST_GeomFromText(p.outline), 4326),
      reference_latitude = p.lat, reference_longitude = p.lon,
      active = true, updated_at = now()
    FROM plan_sub_sectors p JOIN plan_sectors ps ON ps.n = p.sector_n, sectors s
   WHERE s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.sector_n
     AND ss.sector_id = s.id AND ss.short_code = 'SS' || p.n;
  SELECT s.id, pid, 'Sub-sector ' || p.n, 'SS' || p.n, 'Plan ' || ps.letter || p.n || ' · 2026 Sectoring Plan (BE.C.206)',
         p.lat, p.lon, ST_SetSRID(ST_GeomFromText(p.outline), 4326)
    FROM plan_sub_sectors p JOIN plan_sectors ps ON ps.n = p.sector_n
    JOIN sectors s ON s.project_id = pid AND s.planting_year_id = yid AND s.short_code = 'S' || p.sector_n
   WHERE NOT EXISTS (SELECT 1 FROM sub_sectors ss WHERE ss.sector_id = s.id AND ss.short_code = 'SS' || p.n);

  -- Other 2026 sub-sectors and sectors: removed when unused, kept when trees or assignments refer to them.
  DELETE FROM sub_sectors ss USING sectors s
   WHERE ss.sector_id = s.id AND s.project_id = pid AND s.planting_year_id = yid
     AND NOT EXISTS (SELECT 1 FROM plan_sub_sectors p WHERE s.short_code = 'S' || p.sector_n AND ss.short_code = 'SS' || p.n)
     AND NOT EXISTS (SELECT 1 FROM trees t WHERE t.sub_sector_id = ss.id)
     AND NOT EXISTS (SELECT 1 FROM user_project_assignments a WHERE a.sub_sector_id = ss.id);
  DELETE FROM sectors s
   WHERE s.project_id = pid AND s.planting_year_id = yid
     AND NOT EXISTS (SELECT 1 FROM plan_sectors p WHERE s.short_code = 'S' || p.n)
     AND NOT EXISTS (SELECT 1 FROM sub_sectors ss WHERE ss.sector_id = s.id)
     AND NOT EXISTS (SELECT 1 FROM trees t WHERE t.sector_id = s.id)
     AND NOT EXISTS (SELECT 1 FROM user_project_assignments a WHERE a.sector_id = s.id);

  SELECT count(*) INTO kept FROM sub_sectors ss JOIN sectors s ON s.id = ss.sector_id
   WHERE s.project_id = pid AND s.planting_year_id = yid
     AND NOT EXISTS (SELECT 1 FROM plan_sub_sectors p WHERE s.short_code = 'S' || p.sector_n AND ss.short_code = 'SS' || p.n);
  RAISE NOTICE '2026 sectoring plan applied; % earlier 2026 sub-sector(s) outside the plan kept because records use them', kept;
END $$;
